public class Main {
    static int modify(int[] arr, int idx) {
        arr[idx] = arr[idx] * 2;
        return arr[idx] + idx;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};
        int sum = 0;

        for (int i = 0; i < numbers.length; i++) {
            sum += modify(numbers, i);
        }

        for (int i = 0; i < numbers.length; i++) {
            System.out.print(numbers[i] + " ");
        }
        System.out.println();
        System.out.println("sum=" + sum);
    }
}

#include <stdio.h>

int calc(int *p, int n) {
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += *(p + i);
        if (i % 2 == 0) {
            *(p + i) = *(p + i) + 10;
        }
    }
    return result;
}

int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    int total = calc(arr, 5);

    for (int i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
    printf("total=%d\n", total);

    return 0;
}

